{"path":"/root/solve.py","content":"#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')

RUNS_14 = 26
RUNS_28 = 13
THRESHOLD = 6000

ASSUMPTIONS = {
    "runs_per_year_14_day": 26,
    "runs_per_year_28_day": 13,
    "switch_threshold_usd": 6000,
    "override_rule": "highest numeric approved rev with non-empty active_labs, else default_active_labs",
    "holdout_rule": "exclude holdout_state=exclude",
    "adjustment_rule": "missing network_tier adjustment defaults to 0.0"
}


def read_json(name):
    with (ROOT / name).open() as f:
        return json.load(f)


def read_csv(name):
    with (ROOT / name).open(newline='') as f:
        return list(csv.DictReader(f))


def money(value):
    return round(float(value), 2)


def required_float(value, context):
    if value is None or str(value).strip() == '':
        raise ValueError(f"Missing numeric value for {context}")
    return float(value)


def main():
    manifest = read_json('panel_manifest.json')
    holdouts = read_json('holdouts.json')
    template = read_json('report_template.json')

    contract_rows = read_csv('contract_terms.csv')
    adjustment_rows = read_csv('network_adjustments.csv')
    override_rows = read_csv('lab_capacity_overrides.csv')
    shipper_rows = read_csv('shipper_cost.csv')

    exclude_codes = {
        row['panel_code']
        for row in holdouts.get('holdouts', [])
        if row.get('holdout_state') == 'exclude'
    }

    panels = []
    for cluster in manifest.get('service_clusters', []):
        for panel in cluster.get('panels', []):
            if panel.get('analysis_mode') == 'review' and panel.get('panel_code') not in exclude_codes:
                panels.append(panel)

    # Resolve latest current contract row per panel_ref by lexicographic ISO week/date.
    current_contracts = [row for row in contract_rows if row.get('status_flag') == 'current']

    adjustments = {
        row['network_tier']: float(row['network_adjustment_per_run_per_lab_usd'])
        for row in adjustment_rows
        if row.get('network_tier')
    }

    shippers = {
        row['shipper_class']: float(row['shipper_cost_usd'])
        for row in shipper_rows
        if row.get('shipper_class')
    }

    best_overrides = {}
    for row in override_rows:
        if row.get('approval') != 'approved':
            continue
        if str(row.get('rev', '')).strip() == '' or str(row.get('active_labs', '')).strip() == '':
            continue
        rev = float(row['rev'])
        code = row['panel_code']
        if code not in best_overrides or rev > best_overrides[code]['rev']:
            best_overrides[code] = {
                'rev': rev,
                'active_labs': int(float(row['active_labs']))
            }

    output_panels = []
    for panel in panels:
        panel_code = panel['panel_code']
        panel_refs = {panel['panel_name'], *panel.get('alias_labels', [])}
        matches = [row for row in current_contracts if row.get('panel_ref') in panel_refs]
        if not matches:
            raise ValueError(f"No current contract row matched panel {panel_code} refs {sorted(panel_refs)}")
        contract = max(matches, key=lambda row: row.get('effective_week', ''))
        base_payment = required_float(contract['base_payment_per_run_per_lab_usd'], f"contract {panel_code}")

        network_adjustment = adjustments.get(panel.get('network_tier'), 0.0)
        active_labs = best_overrides.get(panel_code, {}).get('active_labs', int(panel['default_active_labs']))
        shipper_class = panel['shipper_class']
        if shipper_class not in shippers:
            raise ValueError(f"No shipper cost for class {shipper_class} used by {panel_code}")
        shipper_cost = shippers[shipper_class]

        reagent_cost_per_1000 = required_float(panel['reagent_cost_per_1000_tests_usd'], f"reagent {panel_code}")
        tests_14 = required_float(panel['tests_per_lab_per_run_14_day'], f"tests 14-day {panel_code}")
        tests_28 = required_float(panel['tests_per_lab_per_run_28_day'], f"tests 28-day {panel_code}")

        total_payment = base_payment + network_adjustment

        annual_revenue_14 = total_payment * active_labs * RUNS_14
        annual_reagent_14 = reagent_cost_per_1000 * active_labs * tests_14 * RUNS_14 / 1000
        annual_shipper_14 = shipper_cost * RUNS_14
        annual_margin_14 = annual_revenue_14 - annual_reagent_14 - annual_shipper_14

        annual_revenue_28 = total_payment * active_labs * RUNS_28
        annual_reagent_28 = reagent_cost_per_1000 * active_labs * tests_28 * RUNS_28 / 1000
        annual_shipper_28 = shipper_cost * RUNS_28
        annual_margin_28 = annual_revenue_28 - annual_reagent_28 - annual_shipper_28

        margin_diff = annual_margin_28 - annual_margin_14

        output_panels.append({
            "panel_code": panel_code,
            "panel_name": panel['panel_name'],
            "active_labs": active_labs,
            "base_payment_per_run_per_lab_usd": money(base_payment),
            "network_adjustment_per_run_per_lab_usd": money(network_adjustment),
            "total_payment_per_run_per_lab_usd": money(total_payment),
            "reagent_cost_per_1000_tests_usd": money(reagent_cost_per_1000),
            "shipper_cost_usd": money(shipper_cost),
            "annual_revenue_14_day_usd": money(annual_revenue_14),
            "annual_reagent_cost_14_day_usd": money(annual_reagent_14),
            "annual_shipper_cost_14_day_usd": money(annual_shipper_14),
            "annual_margin_14_day_usd": money(annual_margin_14),
            "annual_revenue_28_day_usd": money(annual_revenue_28),
            "annual_reagent_cost_28_day_usd": money(annual_reagent_28),
            "annual_shipper_cost_28_day_usd": money(annual_shipper_28),
            "annual_margin_28_day_usd": money(annual_margin_28),
            "annual_margin_difference_28_minus_14_usd": money(margin_diff)
        })

    output_panels.sort(key=lambda row: row['panel_code'])

    total_margin_14 = sum(row['annual_margin_14_day_usd'] for row in output_panels)
    total_margin_28 = sum(row['annual_margin_28_day_usd'] for row in output_panels)
    total_diff = sum(row['annual_margin_difference_28_minus_14_usd'] for row in output_panels)
    abs_diff = abs(total_diff)
    decision = 'adopt_28_day' if abs_diff < THRESHOLD else 'keep_14_day'

    totals = {
        "total_annual_margin_14_day_usd": money(total_margin_14),
        "total_annual_margin_28_day_usd": money(total_margin_28),
        "total_annual_margin_difference_28_minus_14_usd": money(total_diff),
        "absolute_total_margin_difference_usd": money(abs_diff)
    }

    report = {
        "metadata": template["metadata"],
        "audit_notes": template["audit_notes"],
        "analysis": {
            "assumptions": ASSUMPTIONS,
            "panels": output_panels,
            "totals": totals,
            "recommendation": {
                "decision": decision,
                "justification": (
                    f"Absolute total margin difference is ${totals['absolute_total_margin_difference_usd']:.2f}, "
                    f"compared with the ${THRESHOLD:.2f} switch threshold."
                )
            }
        }
    }

    with (ROOT / 'diagpanel_policy_report.json').open('w') as f:
        json.dump(report, f, indent=2)
        f.write('\n')

    summary_lines = [
        f"Total 14-day margin (USD): {totals['total_annual_margin_14_day_usd']:.2f}",
        f"Total 28-day margin (USD): {totals['total_annual_margin_28_day_usd']:.2f}",
        f"Absolute difference (USD): {totals['absolute_total_margin_difference_usd']:.2f}",
        f"Final decision: {decision}",
    ]
    (ROOT / 'diagpanel_policy_summary.md').write_text('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
